import{_ as a,o as s,c as i,X as t}from"./chunks/framework.6lxT3esk.js";const k=JSON.parse('{"title":"Installation","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/installation.md","filePath":"installation.md"}'),n={name:"rust/docs/installation.md"};function l(o,e,r,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Rust 1.96 is used for the guide examples; edition 2024. The published crate declares Rust 1.89 as its minimum version.</li><li>Linux: storage uses Unix file interfaces, and the loader uses Linux memory, futex, and I/O interfaces.</li><li>The default loader backend requires <code>io_uring</code>. Select <code>IoBackend::Pread</code> explicitly when the environment disables it.</li><li>On x86-64, the runtime selects supported SIMD kernels. Scalar kernels are also available; see <a href="/CellPack/rust/docs/performance.html#runtime-kernels">runtime configuration</a>.</li></ul><p>The Rust core has no Python dependency. <code>crates/pycellpack</code> is the separate PyO3 binding crate and is not needed for the workflows in this manual.</p><h2 id="add-cellpack-from-crates-io" tabindex="-1">Add CellPack from crates.io <a class="header-anchor" href="#add-cellpack-from-crates-io" aria-label="Permalink to &quot;Add CellPack from crates.io&quot;">​</a></h2><p><a href="https://crates.io/crates/cellpack" target="_blank" rel="noreferrer">CellPack is published on crates.io</a>. Add it to an existing Rust application:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cellpack@0.1.0</span></span></code></pre></div><p>Or add the dependency directly to your application&#39;s <code>Cargo.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cellpack = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span></span></code></pre></div><p>Cargo downloads the crate and its dependencies from the registry. No CellPack repository checkout is required.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Enabled by default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>serde</code></td><td>No</td><td>Serde derives for cost-model types</td></tr></tbody></table><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cellpack = { version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, features = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;serde&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>The binary plan format and <code>CostModel::to_bytes</code> / <code>from_bytes</code> do not require <code>serde</code>. Profiling requires no build feature: timed and untimed loader instances are included in the same build.</p><h2 id="check-your-application" tabindex="-1">Check your application <a class="header-anchor" href="#check-your-application" aria-label="Permalink to &quot;Check your application&quot;">​</a></h2><p>Run these commands from your application&#39;s directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --open</span></span></code></pre></div><p>The API entry point is <code>target/doc/cellpack/index.html</code>. The published Rust API is also available on <a href="https://docs.rs/cellpack/0.1.0/cellpack/" target="_blank" rel="noreferrer">docs.rs</a>.</p><p>On systems that restrict compilation on development machines, run compilation, examples, and full documentation builds on an authorized compute node. See <a href="/CellPack/rust/docs/contributing.html">documentation development</a> for the documentation toolchain.</p><h2 id="run-a-first-example" tabindex="-1">Run a first example <a class="header-anchor" href="#run-a-first-example" aria-label="Permalink to &quot;Run a first example&quot;">​</a></h2><p>Create an application and add the published crate:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cellpack-demo</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cellpack-demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cellpack@0.1.0</span></span></code></pre></div><p>Save the <a href="/CellPack/downloads/rust/quickstart.rs" target="_self">quickstart source</a> as <code>src/main.rs</code>, then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output/quickstart</span></span></code></pre></div><p>The example generates its own tiny matrix, writes <code>matrix.cpk</code> in the supplied directory, and checks its decoded contents. Use a dedicated output directory: rerunning an example overwrites its named outputs. Continue with the <a href="/CellPack/rust/docs/quickstart.html">quickstart</a> for the full source. Other guide programs that declare <code>mod common;</code> also need <a href="/CellPack/downloads/rust/common.rs" target="_self">common.rs</a> saved as <code>src/common.rs</code>.</p>`,25)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
